({
  _checkInvariants() {
    if (this.data) {
      this.invariant(typeof this.data.text === "string", "Invariant: data.text must be a string");
      this.invariant(typeof this.data.wordCount === "number" && this.data.wordCount >= 0, "Invariant: data.wordCount must be non-negative");
      this.invariant(typeof this.data.averageWordLength === "number" && this.data.averageWordLength >= 0, "Invariant: data.averageWordLength must be non-negative");
      this.invariant(typeof this.data.readingTimeMinutes === "number" && this.data.readingTimeMinutes >= 0, "Invariant: data.readingTimeMinutes must be non-negative");
      this.invariant(Array.isArray(this.data.frequencies), "Invariant: data.frequencies must be an array");
    }
  },

  init(msg) {
    this.ensure(!msg || typeof msg === "object", "init accepts an optional object message");

    this.data = {
      text: "",
      wordCount: 0,
      averageWordLength: 0,
      readingTimeMinutes: 0,
      frequencies: []
    };

    this._checkInvariants();
    this.changed("data", this.data);

    const result = { initialized: true };
    this.ensure(result.initialized === true, "init must succeed");
    return result;
  },

  analyzeText(msg) {
    this.ensure(
      msg && msg.payload && typeof msg.payload.text === "string",
      "analyzeText requires msg.payload.text to be a string"
    );

    const text = msg.payload.text;
    const words = text.match(/\b[\w'-]+\b/g) || [];
    const wordCount = words.length;
    const totalChars = words.reduce((sum, w) => sum + w.length, 0);
    const averageWordLength = wordCount > 0 ? +(totalChars / wordCount).toFixed(2) : 0;
    const readingTimeMinutes = wordCount > 0 ? +(wordCount / 200).toFixed(2) : 0;

    const frequencyMap = {};
    for (let i = 0; i < words.length; i++) {
      const normalized = words[i].toLowerCase();
      frequencyMap[normalized] = (frequencyMap[normalized] || 0) + 1;
    }

    const frequencies = Object.keys(frequencyMap)
      .map(word => ({ word, count: frequencyMap[word] }))
      .sort((a, b) => b.count - a.count);

    this.data = {
      text,
      wordCount,
      averageWordLength,
      readingTimeMinutes,
      frequencies
    };

    this._checkInvariants();
    this.changed("analysis", this.data);

    const result = {
      wordCount: this.data.wordCount,
      averageWordLength: this.data.averageWordLength,
      readingTimeMinutes: this.data.readingTimeMinutes,
      readingTime: `${this.data.readingTimeMinutes} min`
    };

    this.ensure(
      typeof result.wordCount === "number" &&
      typeof result.averageWordLength === "number" &&
      typeof result.readingTimeMinutes === "number",
      "analyzeText must return valid metrics"
    );

    return result;
  },

  topWords(msg) {
    const limit = (msg && msg.payload && typeof msg.payload.limit === "number") ? msg.payload.limit : 10;
    this.ensure(
      typeof limit === "number" && limit >= 0 && Number.isInteger(limit),
      "topWords requires limit to be a non-negative integer"
    );

    if (!this.data || !Array.isArray(this.data.frequencies)) {
      this.data = {
        text: "",
        wordCount: 0,
        averageWordLength: 0,
        readingTimeMinutes: 0,
        frequencies: []
      };
      this._checkInvariants();
    }

    const result = this.data.frequencies.slice(0, limit);

    this.ensure(
      Array.isArray(result) && result.length <= limit,
      "topWords must return an array of items bounded by limit"
    );

    return result;
  }
})
